local ProcessionalCanopyMaker = {}
local PRODUCTS = {
    simple_linen_canopy = { name = "Preprost laneni procesijski baldahin", linenCost = 4, woodCost = 3, ropeCost = 2, time = 6, cost = 200, prestige = 8, happiness = 3, description = "Preprost laneni procesijski baldahin za procesije." },
    silk_draped_canopy = { name = "Sviloobeseni procesijski baldahin", silkCost = 3, linenCost = 2, woodCost = 3, ropeCost = 2, time = 9, cost = 480, prestige = 18, happiness = 4, description = "Sviloobeseni procesijski baldahin za trgovce." },
    silver_trimmed_canopy = { name = "Srebrnoobrobljeni procesijski baldahin", silkCost = 3, silverCost = 1, linenCost = 2, woodCost = 3, ropeCost = 2, time = 13, cost = 1100, prestige = 30, happiness = 5, description = "Srebrnoobrobljeni procesijski baldahin za plemiče." },
    gold_trimmed_canopy = { name = "Zlatookrasni procesijski baldahin", silkCost = 4, goldCost = 1, silverCost = 1, linenCost = 2, woodCost = 3, ropeCost = 2, time = 17, cost = 2500, prestige = 45, happiness = 7, description = "Zlatookrasni procesijski baldahin za visoke plemiče." },
    jewel_set_canopy = { name = "Draguljasta procesijski baldahin", silkCost = 4, goldCost = 2, silverCost = 1, linenCost = 2, woodCost = 3, ropeCost = 2, jewelCost = 1, time = 21, cost = 5200, prestige = 60, happiness = 9, description = "Procesijski baldahin z draguljem za visoko plemstvo." },
    royal_grand_canopy = { name = "Kraljevski veliki procesijski baldahin", silkCost = 6, goldCost = 3, silverCost = 2, linenCost = 2, woodCost = 4, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 28, cost = 11000, prestige = 80, happiness = 14, description = "Veliki kraljevski procesijski baldahin z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    canopy_workshop = { name = "Baldahinska delavnica", cost = { gold = 300, wood = 160, stone = 120, silk = 6, linen = 6 }, upkeep = 7, qualityBonus = 5 },
    ceremonial_loft = { name = "Slovesna podstrešje", cost = { gold = 1100, wood = 280, stone = 240, silver = 6, gold = 4 }, upkeep = 25, qualityBonus = 18 },
    master_canopy_atelier = { name = "Mojstrski baldahinski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_ceremony_palace = { name = "Kraljevska slovesna palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
ProcessionalCanopyMaker.silkStock = 14; ProcessionalCanopyMaker.linenStock = 12; ProcessionalCanopyMaker.woodStock = 16; ProcessionalCanopyMaker.ropeStock = 10; ProcessionalCanopyMaker.silverStock = 6; ProcessionalCanopyMaker.goldStock = 6; ProcessionalCanopyMaker.jewelStock = 4; ProcessionalCanopyMaker.pearlStock = 4
ProcessionalCanopyMaker.productStock = {}; ProcessionalCanopyMaker.buildings = {}; ProcessionalCanopyMaker.maker = nil; ProcessionalCanopyMaker.activeMaking = {}; ProcessionalCanopyMaker.totalProducts = 0; ProcessionalCanopyMaker.dayTimer = 0
function ProcessionalCanopyMaker.init() ProcessionalCanopyMaker.silkStock=14; ProcessionalCanopyMaker.linenStock=12; ProcessionalCanopyMaker.woodStock=16; ProcessionalCanopyMaker.ropeStock=10; ProcessionalCanopyMaker.silverStock=6; ProcessionalCanopyMaker.goldStock=6; ProcessionalCanopyMaker.jewelStock=4; ProcessionalCanopyMaker.pearlStock=4; ProcessionalCanopyMaker.productStock={}; ProcessionalCanopyMaker.buildings={}; ProcessionalCanopyMaker.maker=nil; ProcessionalCanopyMaker.activeMaking={}; ProcessionalCanopyMaker.totalProducts=0; ProcessionalCanopyMaker.dayTimer=0; print("[ProcessionalCanopyMaker] Royal Processional Canopy Maker System initialized (6 products, 4 buildings)") end
function ProcessionalCanopyMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ProcessionalCanopyMaker.maker={name=n or ("Baldahinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Baldahinar najet: %s (spretnost: %d)",ProcessionalCanopyMaker.maker.name,s),"success") end; return true end
function ProcessionalCanopyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ProcessionalCanopyMaker.build(id) local ok,e=ProcessionalCanopyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ProcessionalCanopyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ProcessionalCanopyMaker.getQualityBonus() local b=0; for _,bd in ipairs(ProcessionalCanopyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ProcessionalCanopyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and ProcessionalCanopyMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.linenCost and ProcessionalCanopyMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.woodCost and ProcessionalCanopyMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and ProcessionalCanopyMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and ProcessionalCanopyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ProcessionalCanopyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ProcessionalCanopyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ProcessionalCanopyMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ProcessionalCanopyMaker.buildings==0 then return false,"Potrebna baldahinska delavnica" end; if not ProcessionalCanopyMaker.maker then return false,"Potreben baldahinar" end; return true end
function ProcessionalCanopyMaker.make(pt,qty) qty=qty or 1; local ok,e=ProcessionalCanopyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then ProcessionalCanopyMaker.silkStock=ProcessionalCanopyMaker.silkStock-d.silkCost*qty end; if d.linenCost then ProcessionalCanopyMaker.linenStock=ProcessionalCanopyMaker.linenStock-d.linenCost*qty end; if d.woodCost then ProcessionalCanopyMaker.woodStock=ProcessionalCanopyMaker.woodStock-d.woodCost*qty end; if d.ropeCost then ProcessionalCanopyMaker.ropeStock=ProcessionalCanopyMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then ProcessionalCanopyMaker.silverStock=ProcessionalCanopyMaker.silverStock-d.silverCost*qty end; if d.goldCost then ProcessionalCanopyMaker.goldStock=ProcessionalCanopyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ProcessionalCanopyMaker.jewelStock=ProcessionalCanopyMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ProcessionalCanopyMaker.pearlStock=ProcessionalCanopyMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ProcessionalCanopyMaker.maker then t=math.max(1,t-math.floor(ProcessionalCanopyMaker.maker.skill/12)) end; table.insert(ProcessionalCanopyMaker.activeMaking,{id="processionalcanopy_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ProcessionalCanopyMaker.completeMaking(m) local q=1.0+(ProcessionalCanopyMaker.getQualityBonus()/100); if ProcessionalCanopyMaker.maker then q=q+(ProcessionalCanopyMaker.maker.skill/140) end; q=math.min(2.5,q); ProcessionalCanopyMaker.productStock[m.productType]=(ProcessionalCanopyMaker.productStock[m.productType] or 0)+m.quantity; ProcessionalCanopyMaker.totalProducts=ProcessionalCanopyMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ProcessionalCanopyMaker.maker then ProcessionalCanopyMaker.maker.itemsMade=ProcessionalCanopyMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ProcessionalCanopyMaker.maker.skill=math.min(100,ProcessionalCanopyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Procesijski baldahin izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"processionalcanopy.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ProcessionalCanopyMaker.update(dt) if not _G.state then return end; ProcessionalCanopyMaker.dayTimer=ProcessionalCanopyMaker.dayTimer+dt; if ProcessionalCanopyMaker.dayTimer>=30 then ProcessionalCanopyMaker.dayTimer=0; for i=#ProcessionalCanopyMaker.activeMaking,1,-1 do local m=ProcessionalCanopyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ProcessionalCanopyMaker.completeMaking(m); table.remove(ProcessionalCanopyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ProcessionalCanopyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ProcessionalCanopyMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ProcessionalCanopyMaker.getStats() return {silkStock=ProcessionalCanopyMaker.silkStock,linenStock=ProcessionalCanopyMaker.linenStock,woodStock=ProcessionalCanopyMaker.woodStock,ropeStock=ProcessionalCanopyMaker.ropeStock,silverStock=ProcessionalCanopyMaker.silverStock,goldStock=ProcessionalCanopyMaker.goldStock,jewelStock=ProcessionalCanopyMaker.jewelStock,pearlStock=ProcessionalCanopyMaker.pearlStock,productStock=ProcessionalCanopyMaker.productStock,numBuildings=#ProcessionalCanopyMaker.buildings,hasMaker=ProcessionalCanopyMaker.maker~=nil,makerName=ProcessionalCanopyMaker.maker and ProcessionalCanopyMaker.maker.name or "—",makerSkill=ProcessionalCanopyMaker.maker and ProcessionalCanopyMaker.maker.skill or 0,activeMaking=#ProcessionalCanopyMaker.activeMaking,totalProducts=ProcessionalCanopyMaker.totalProducts} end
return ProcessionalCanopyMaker
